struct Val {
    long double fi, se;
    Val(double a=0.0, double b=0.0): fi(a), se(b) {}
};

Val combine(const Val& a, const Val& b) {
    return Val(a.fi + b.fi, a.se + b.se);
}

Val subtract(const Val& a, const Val& b) {
    return Val(a.fi - b.fi, a.se - b.se);
}

Val multiply(const Val& a, long double w) {
    return Val(a.fi * w, a.se * w);
}

Val divide(const Val& a, long double w) {
    return Val(a.fi / w, a.se / w);
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> p(n);
    for (int i=0; i<n; ++i) cin >> p[i];

    for (int idx=0; idx<n; ++idx) {
        vector<Val> dp(1<<n, Val(0.0, 0.0));
        for (int mask=0; mask<(1<<n); ++mask) {
            if (mask==0) {
                dp[mask]=Val(1.0, 0.0);
            }
        }
        for (int mask=1; mask<(1<<n); ++mask) {
            if (mask & (1<<idx)) continue;
            Val sum(0.0, 0.0);
            double same=0.0;
            for (int j=0; j<n; ++j) {
