                    same+=p[j];
                    sum= combine(sum, multiply(dp[mask^(1<<j)], p[j]));
                }
            }
            dp[mask]= divide(sum, 1.0 - same);
        }
        Val total(1.0, 0.0);
        for (int mask=1; mask<(1<<n); ++mask) {
            if (!(mask & (1<<idx))) {
                total= combine(total, dp[mask]);
            }
        }
        double alpha= (1.0 - total.se)/total.fi;
        Val bad(0.0, 0.0);
        for (int mask=0; mask<(1<<n); ++mask) {
            if (mask & (1<<idx)) continue;
            if (__builtin_popcount(mask)>=k) {
                bad= combine(bad, dp[mask]);
            }
        }
        cout << fixed << setprecision(12) << 1.0 - (alpha*bad.fi + bad.se) << (idx+1==n ? '\n' : ' ');
    }
    return 0;
