import java.util.*;
import java.io.*;

public class Main {
    static class Val {
        double fi, se;
        Val(double a, double b) {
            this.fi = a;
            this.se = b;
        }
        Val() {
            this(0.0, 0.0);
        }
    }

    static Val combine(Val a, Val b) {
        return new Val(a.fi + b.fi, a.se + b.se);
    }

    static Val subtract(Val a, Val b) {
        return new Val(a.fi - b.fi, a.se - b.se);
    }

    static Val multiply(Val a, double w) {
        return new Val(a.fi * w, a.se * w);
    }

    static Val divide(Val a, double w) {
        return new Val(a.fi / w, a.se / w);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        for (int idx = 0; idx < n; idx++) {
            int size = 1 << n;
            Val[] dp = new Val[size];
            for (int i = 0; i < size; i++) {
                dp[i] = new Val(0.0, 0.0);
            }
            for (int mask = 0; mask < size; mask++) {
                if (mask == 0) {
                    dp[mask] = new Val(1.0, 0.0);
                }
            }
            for (int mask = 1; mask < size; mask++) {
                if ((mask & (1 << idx)) != 0) continue;
                Val sum = new Val(0.0, 0.0);
                double same = 0.0;
                for (int j = 0; j < n; j++) {
                    if (j != idx && ((mask & (1 << j)) != 0)) {
                        same += p[j];
                        int prevMask = mask ^ (1 << j);
                        sum = combine(sum, multiply(dp[prevMask], p[j]));
                    }
                }
                dp[mask] = divide(sum, 1.0 - same);
            }
            Val total = new Val(1.0, 0.0);
            for (int mask = 1; mask < size; mask++) {
                if ((mask & (1 << idx)) == 0) {
                    total = combine(total, dp[mask]);
                }
            }
            double alpha = (1.0 - total.se) / total.fi;
            Val bad = new Val(0.0, 0.0);
            for (int mask = 0; mask < size; mask++) {
                if ((mask & (1 << idx)) != 0) continue;
                if (Integer.bitCount(mask) >= k) {
                    bad = combine(bad, dp[mask]);
                }
            }
            double result = 1.0 - (alpha * bad.fi + bad.se);
            System.out.printf(Locale.US, "%.12f%s", result, (idx + 1 == n) ? "\n" : " ");
        }
        sc.close();
    }
}
